-- Real PostgreSQL OAuth, role-drop and tenant-isolation tests. Fixtures roll back.
begin;
do $$
declare u uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); w uuid; other uuid; obj uuid; foreign_obj uuid; rec uuid; hidden uuid; private_note uuid; client_id uuid; flow text:=repeat('1',64); code text:=repeat('2',64); access_hash text:=repeat('3',64); refresh_hash text:=repeat('4',64); resource text:='https://zyliad.example.test/api/mcp'; redirect_uri text:='http://127.0.0.1:45678/callback'; challenge text:=repeat('a',43); r jsonb; a jsonb; gid uuid; cmd uuid; rid uuid:=gen_random_uuid(); row_id uuid; ver integer;
begin
 insert into auth.users(id,email) values(u,'mcp-owner@example.test'),(v,'mcp-member@example.test'),(b,'mcp-other@example.test');
 perform set_config('request.jwt.claim.sub',u::text,true); perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 w:=public.create_workspace('MCP A');
 insert into public.memberships(workspace_id,user_id,role,display_name) values(w,v,'member','Member');
 select id into obj from public.objects where workspace_id=w and slug='people';
 insert into public.records(workspace_id,object_id,display_name) values(w,obj,'Visible A') returning id into rec;
 insert into public.notes(workspace_id,record_id,title,content,private,author_id) values(w,rec,'Private member','Secret private text',true,v) returning id into private_note;
 perform set_config('request.jwt.claim.sub',b::text,true); perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 other:=public.create_workspace('MCP B');
 select id into foreign_obj from public.objects where workspace_id=other and slug='people';
 insert into public.records(workspace_id,object_id,display_name) values(other,foreign_obj,'Secret B') returning id into hidden;
 execute 'set local role service_role';
 r:=public.mcp_oauth('register',jsonb_build_object('client_name','SDK fixture','redirect_uris',jsonb_build_array(redirect_uri)));client_id:=(r->>'client_id')::uuid;
 r:=public.mcp_oauth('begin',jsonb_build_object('flow_hash',flow,'client_id',client_id,'redirect_uri','https://evil.example/cb','state','client-state','code_challenge',challenge,'resource',resource,'scope',jsonb_build_array('records:read')));
 if r->>'error'<>'invalid_client' then raise exception 'Unregistered redirect allowed';end if;
 r:=public.mcp_oauth('begin',jsonb_build_object('flow_hash',flow,'client_id',client_id,'redirect_uri',redirect_uri,'state','client-state','code_challenge',challenge,'resource',resource,'scope',jsonb_build_array('records:read','notes:read','tasks:read','configuration:read','crm:write')));
 if r ? 'error' then raise exception 'Authorization begin failed: %',r;end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',u::text,true); perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.mcp_consent(flow,other,array['records:read'],code,true);raise exception 'Foreign workspace consent allowed';exception when insufficient_privilege then null;end;
 begin perform public.mcp_consent(flow,w,array['documents:read'],code,true);raise exception 'Scope escalation allowed';exception when insufficient_privilege then null;end;
 r:=public.mcp_consent(flow,w,array['records:read','notes:read','tasks:read','configuration:read','crm:write'],code,true);
 if r->>'redirect_uri'<>redirect_uri or r->>'state'<>'client-state' then raise exception 'Consent lost registered redirect/state';end if;
 begin perform public.mcp_consent(flow,w,array['records:read'],code,true);raise exception 'Consent replay allowed';exception when invalid_parameter_value then null;end;
 begin perform public.mcp_request(access_hash,'session',jsonb_build_object('resource',resource));raise exception 'User can invoke service RPC';exception when insufficient_privilege then null;end;
 begin perform 1 from relay_private.mcp_tokens;raise exception 'User can read hashes';exception when insufficient_privilege then null;end;
 execute 'set local role service_role';
 r:=public.mcp_oauth('exchange',jsonb_build_object('code_hash',code,'client_id',client_id,'redirect_uri',redirect_uri,'resource',resource,'challenge',repeat('b',43),'access_hash',access_hash,'new_refresh_hash',refresh_hash));
 if r->>'error'<>'invalid_grant' then raise exception 'Bad PKCE accepted';end if;
 r:=public.mcp_oauth('exchange',jsonb_build_object('code_hash',code,'client_id',client_id,'redirect_uri',redirect_uri,'resource','https://evil.example/api/mcp','challenge',challenge,'access_hash',access_hash,'new_refresh_hash',refresh_hash));
 if r->>'error'<>'invalid_grant' then raise exception 'Wrong audience accepted';end if;
 r:=public.mcp_oauth('exchange',jsonb_build_object('code_hash',code,'client_id',client_id,'redirect_uri',redirect_uri,'resource',resource,'challenge',challenge,'access_hash',access_hash,'new_refresh_hash',refresh_hash));
 if (r->>'expires_in')::integer<>3600 then raise exception 'Token exchange failed: %',r;end if;
 r:=public.mcp_oauth('exchange',jsonb_build_object('code_hash',code,'client_id',client_id,'redirect_uri',redirect_uri,'resource',resource,'challenge',challenge,'access_hash',repeat('5',64),'new_refresh_hash',repeat('6',64)));
 if r->>'error'<>'invalid_grant' then raise exception 'Code replay allowed';end if;
 r:=public.mcp_request(access_hash,'session',jsonb_build_object('resource',resource));gid:=(r->>'connection_id')::uuid;
 if r->>'workspace_id'<>w::text or r ? 'user_id' then raise exception 'Session binding failed: %',r;end if;
 -- An untrusted payload cannot change workspace. Reads run under authenticated RLS.
 r:=public.mcp_request(access_hash,'search',jsonb_build_object('resource',resource,'kind','record','workspace_id',other,'filters','{}'::jsonb));
 if (r->>'total')::integer<>1 or r::text like '%Secret B%' then raise exception 'Role-drop / tenant search failed: %',r;end if;
 r:=public.mcp_request(access_hash,'source',jsonb_build_object('resource',resource,'kind','record','id',hidden));
 if jsonb_array_length(r->'data')<>0 then raise exception 'Foreign external ID leaked';end if;
 r:=public.mcp_request(access_hash,'source',jsonb_build_object('resource',resource,'kind','note','id',private_note));
 if jsonb_array_length(r->'data')<>0 then raise exception 'Other user private note leaked';end if;
 r:=public.mcp_request(access_hash,'search',jsonb_build_object('resource',resource,'kind','document'));
 if r->>'error'<>'forbidden' then raise exception 'Missing scope ignored';end if;
 a:=public.mcp_request(access_hash,'prepare',jsonb_build_object('resource',resource,'action','create_task','request_id',rid,'values',jsonb_build_object('title','Explicit task','record_id',rec)));cmd:=(a->>'id')::uuid;
 if a->>'status'<>'pending' then raise exception 'Proposal not pending: %',a;end if;
 r:=public.mcp_request(access_hash,'prepare',jsonb_build_object('resource',resource,'action','create_task','request_id',rid,'values',jsonb_build_object('title','Explicit task','record_id',rec)));
 if r->>'id'<>cmd::text then raise exception 'Duplicate proposal';end if;
 r:=public.mcp_request(access_hash,'prepare',jsonb_build_object('resource',resource,'action','create_task','request_id',rid,'values',jsonb_build_object('title','Different task')));
 if r->>'error'<>'conflict' then raise exception 'Idempotency collision accepted';end if;
 execute 'reset role';
 if exists(select 1 from public.tasks where workspace_id=w and title='Explicit task') then raise exception 'Model silently executed write';end if;
 perform set_config('request.jwt.claim.sub',v::text,true); perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.mcp_manage(w,'approve',cmd);raise exception 'Different user approved';exception when insufficient_privilege then null;end;
 r:=public.mcp_manage(w,'list');if jsonb_array_length(r->'connections')<>0 or jsonb_array_length(r->'commands')<>0 then raise exception 'Other user history leaked';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',u::text,true); perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 r:=public.mcp_manage(w,'approve',cmd);row_id:=(r->>'record_id')::uuid;
 if r->>'status'<>'executed' or row_id is null then raise exception 'Human confirmation failed: %',r;end if;
 perform public.mcp_manage(w,'approve',cmd);
 if (select count(*) from public.tasks where workspace_id=w and title='Explicit task')<>1 then raise exception 'Duplicate effect';end if;
 begin perform public.mcp_manage(w,'finish',cmd);raise exception 'Public completion bypass';exception when insufficient_privilege then null;end;
 execute 'set local role service_role';
 a:=public.mcp_request(access_hash,'prepare',jsonb_build_object('resource',resource,'action','create_note','request_id',gen_random_uuid(),'values',jsonb_build_object('content','Private extracted note','private',false)));
 execute 'set local role authenticated';
 r:=public.mcp_manage(w,'approve',(a->>'id')::uuid);
 if not exists(select 1 from public.notes where id=(r->>'record_id')::uuid and private and author_id=u) then raise exception 'Private note declassified';end if;
 execute 'set local role service_role';
 a:=public.mcp_request(access_hash,'prepare',jsonb_build_object('resource',resource,'action','create_task','request_id',gen_random_uuid(),'values',jsonb_build_object('title','Cross tenant FK','record_id',hidden)));
 execute 'set local role authenticated';
 begin perform public.mcp_manage(w,'approve',(a->>'id')::uuid);raise exception 'Foreign linked record accepted';exception when check_violation or foreign_key_violation or insufficient_privilege then null;end;
 execute 'reset role';
 select version into ver from public.records where id=rec;
 execute 'set local role service_role';
 a:=public.mcp_request(access_hash,'prepare',jsonb_build_object('resource',resource,'action','update_record','request_id',gen_random_uuid(),'values',jsonb_build_object('id',rec,'version',ver,'values',jsonb_build_object('display_name','Exact change'))));
 execute 'reset role';update public.records set display_name='Concurrent change' where id=rec;
 execute 'set local role authenticated';
 begin perform public.mcp_manage(w,'approve',(a->>'id')::uuid);raise exception 'Stale proposal overwrote record';exception when serialization_failure then null;end;
 perform public.mcp_manage(w,'reject',(a->>'id')::uuid);
 execute 'reset role';update public.memberships set role='viewer' where workspace_id=w and user_id=u;
 execute 'set local role service_role';
 r:=public.mcp_request(access_hash,'prepare',jsonb_build_object('resource',resource,'action','create_task','request_id',gen_random_uuid(),'values','{"title":"Viewer forbidden"}'::jsonb));
 if r->>'error'<>'forbidden' then raise exception 'Role downgrade ignored';end if;
 execute 'reset role';update public.memberships set role='owner' where workspace_id=w and user_id=u;
 update relay_private.mcp_connections set requests=120 where id=gid;
 execute 'set local role service_role';r:=public.mcp_request(access_hash,'session',jsonb_build_object('resource',resource));
 if r->>'error'<>'rate_limited' then raise exception 'Connection budget ignored';end if;
 execute 'reset role';update relay_private.mcp_connections set requests=0 where id=gid;
 execute 'set local role service_role';
 r:=public.mcp_oauth('refresh',jsonb_build_object('refresh_hash',refresh_hash,'client_id',gen_random_uuid(),'resource',resource,'access_hash',repeat('5',64),'new_refresh_hash',repeat('6',64)));
 if r->>'error'<>'invalid_grant' then raise exception 'Refresh wrong client accepted';end if;
 r:=public.mcp_oauth('refresh',jsonb_build_object('refresh_hash',access_hash,'client_id',client_id,'resource',resource,'access_hash',repeat('5',64),'new_refresh_hash',repeat('6',64)));
 if r->>'error'<>'invalid_grant' then raise exception 'Access used as refresh';end if;
 r:=public.mcp_oauth('refresh',jsonb_build_object('refresh_hash',refresh_hash,'client_id',client_id,'resource',resource,'access_hash',repeat('5',64),'new_refresh_hash',repeat('6',64)));
 if r ? 'error' then raise exception 'Refresh failed: %',r;end if;
 r:=public.mcp_oauth('refresh',jsonb_build_object('refresh_hash',refresh_hash,'client_id',client_id,'resource',resource,'access_hash',repeat('7',64),'new_refresh_hash',repeat('8',64)));
 if r->>'error'<>'invalid_grant' then raise exception 'Refresh replay allowed';end if;
 r:=public.mcp_request(repeat('5',64),'session',jsonb_build_object('resource',resource));
 if r->>'error'<>'unauthorized' then raise exception 'Replayed refresh family still usable';end if;
 execute 'reset role';
 -- Expiry and manual disconnect invalidate access independently of refresh replay.
 insert into relay_private.mcp_connections(client_id,workspace_id,user_id,scopes,resource) values(client_id,w,u,array['records:read','crm:write'],resource) returning id into gid;
 insert into relay_private.mcp_tokens(token_hash,connection_id,kind,expires_at) values(repeat('9',64),gid,'access',now()-interval '1 second');
 execute 'set local role service_role';
 r:=public.mcp_request(repeat('9',64),'session',jsonb_build_object('resource',resource));
 if r->>'error'<>'unauthorized' then raise exception 'Expired token accepted';end if;
 execute 'reset role';update relay_private.mcp_tokens set expires_at=now()+interval '1 hour' where token_hash=repeat('9',64);
 execute 'set local role service_role';
 a:=public.mcp_request(repeat('9',64),'prepare',jsonb_build_object('resource',resource,'action','create_task','request_id',gen_random_uuid(),'values','{"title":"Expired proposal"}'::jsonb));
 execute 'reset role';update relay_private.mcp_commands set expires_at=now()-interval '1 second' where id=(a->>'id')::uuid;
 execute 'set local role authenticated';r:=public.mcp_manage(w,'approve',(a->>'id')::uuid);
 if r->>'status'<>'expired' or exists(select 1 from public.tasks where workspace_id=w and title='Expired proposal') then raise exception 'Expired proposal executed';end if;
 execute 'reset role';update public.memberships set role='viewer' where workspace_id=w and user_id=u;
 execute 'set local role authenticated';perform public.mcp_manage(w,'revoke',gid);
 execute 'set local role service_role';r:=public.mcp_request(repeat('9',64),'session',jsonb_build_object('resource',resource));
 if r->>'error'<>'unauthorized' then raise exception 'Disconnected family still usable';end if;
 execute 'reset role';
 if exists(select 1 from relay_private.mcp_commands where id=(a->>'id')::uuid and payload<>'{}'::jsonb) then raise exception 'Expired payload retained';end if;
 -- The first family has successful audits, the second only expiry/disconnect.
 select connection_id into gid from relay_private.mcp_tokens where token_hash=access_hash;
 if exists(select 1 from pg_roles where rolname='zyliad_mcp' and (rolcanlogin or rolsuper or rolbypassrls)) then raise exception 'Unsafe MCP role';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='relay_private' and c.relname like 'mcp_%' and c.relkind='r' and not c.relrowsecurity) then raise exception 'Private table missing RLS';end if;
 if not exists(select 1 from relay_private.mcp_audit where connection_id=gid and action='search' and result='success') or not exists(select 1 from relay_private.mcp_audit where connection_id=gid and result='executed') then raise exception 'Action outcome audit missing';end if;
 raise notice 'MCP OAuth/PKCE, code and refresh replay, audience, tenant/private-data RLS, typed proposals, exact confirmation, idempotence, conflicts, role downgrade, rate limit and audit passed.';
end $$;
rollback;
